        nr1 = nr0 + (r1-r0)
        for i, row in enumerate(motif):
            out[nr0+i][c0:c1+1] = row
        mark = nr1 + 1
        if mark < h:
            out[mark] = [8 if x != 2 else 2 for x in out[mark]]
    return out


